def word_pattern(pattern, s):
    words = s.split()
    if len(pattern) != len(words):
        return False
    for i in range(len(pattern)):
        for j in range(len(pattern)):                              # rescans every earlier position for a conflict
            if pattern[i] == pattern[j] and words[i] != words[j]:
                return False
            if pattern[i] != pattern[j] and words[i] == words[j]:
                return False
    return True


if __name__ == "__main__":
    print(word_pattern("abba", "dog cat cat dog"))

