import java.util.*;

public class Main {
    boolean wordPattern(String pattern, String s) {
        String[] words = s.split(" ");
        if (pattern.length() != words.length) return false;
        for (int i = 0; i < pattern.length(); i++) {
            for (int j = 0; j < pattern.length(); j++) {                    // rescans every earlier position for a conflict
                boolean samePattern = pattern.charAt(i) == pattern.charAt(j);
                boolean sameWord = words[i].equals(words[j]);
                if (samePattern != sameWord) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.wordPattern("abba", "dog cat cat dog"));
    }
}

