public class Main {
    boolean wordPattern(String pattern, String s) {
        String[] words = s.split(" ");
        if (pattern.length() != words.length) return false;
        Map<Character, String> charToWord = new HashMap<>();
        Map<String, Character> wordToChar = new HashMap<>();
        for (int i = 0; i < pattern.length(); i++) {
            char ch = pattern.charAt(i);
            String word = words[i];
            if (charToWord.containsKey(ch) && !charToWord.get(ch).equals(word)) {
                return false;                                                // this letter already maps elsewhere
            }
            if (wordToChar.containsKey(word) && wordToChar.get(word) != ch) {
                return false;                                                  // this word already maps elsewhere
            }
            charToWord.put(ch, word);
            wordToChar.put(word, ch);
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.wordPattern("abba", "dog cat cat dog"));
    }
}

