bool wordPattern(string pattern, string s) {
    vector<string> words;
    stringstream ss(s);
    string word;
    while (ss >> word) words.push_back(word);
    if (pattern.size() != words.size()) return false;
    unordered_map<char, string> charToWord;
    unordered_map<string, char> wordToChar;
    for (int i = 0; i < (int)pattern.size(); i++) {
        char ch = pattern[i];
        string w = words[i];
        if (charToWord.count(ch) && charToWord[ch] != w) return false;      // this letter already maps elsewhere
        if (wordToChar.count(w) && wordToChar[w] != ch) return false;         // this word already maps elsewhere
        charToWord[ch] = w;
        wordToChar[w] = ch;
    }
    return true;
}

int main() {
    cout << (wordPattern("abba", "dog cat cat dog") ? "true" : "false") << endl;
    return 0;
